#!/bin/sh
# quadcast2s - RGB lighting for the HyperX QuadCast 2 S
# SPDX-License-Identifier: AGPL-3.0-only
#
# Put `quadcast2s` and `quadcast2s-gui` on PATH without a virtualenv and
# without installing anything into Python. Both are two-line wrappers that run
# the source tree in place, so edits take effect immediately -- the same
# property an editable install gives you.
#
# Needs pyusb, and PySide6 for the GUI. On Arch:
#     sudo pacman -S python-pyusb pyside6
#
# Undo with:  rm ~/.local/bin/quadcast2s ~/.local/bin/quadcast2s-gui

set -e

project=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd -P)
bindir=${1:-$HOME/.local/bin}

if [ ! -f "$project/src/quadcast2s/__main__.py" ]; then
    echo "cannot find the source tree under $project" >&2
    exit 1
fi

python3 -c 'import usb.core' 2>/dev/null \
    || echo "warning: pyusb is not installed; the daemon will not start" >&2

mkdir -p "$bindir"

for name in quadcast2s quadcast2s-gui; do
    case $name in
        quadcast2s)     module=quadcast2s ;;
        quadcast2s-gui) module=quadcast2s.gui ;;
    esac
    cat > "$bindir/$name" <<WRAPPER
#!/bin/sh
# Generated by scripts/install-local.sh -- safe to delete.
exec env PYTHONPATH="$project/src" python3 -m $module "\$@"
WRAPPER
    chmod +x "$bindir/$name"
    echo "installed $bindir/$name"
done

case ":$PATH:" in
    *":$bindir:"*) ;;
    *) echo
       echo "note: $bindir is not on your PATH. Add it with:"
       echo "  echo 'export PATH=\"\$PATH:$bindir\"' >> ~/.zshrc" ;;
esac
